/**
 * Pure (DOM-free) rules for the `graphql-transport-ws` subscription socket (live UI bug 2).
 *
 * The worker's graphql-ws context (generated by lokal: `cloudflare/worker.ts`, `makeServer({ context })`)
 * reads the bearer from `connectionParams.Authorization`, i.e. a TOP-LEVEL key of the
 * `connection_init` payload. The client sent `{ headers: { Authorization } }`, so the worker saw no
 * token, built an unauthenticated context, and `requireIdentity` answered every subscription
 * (`onRelayChatMessage`, `onRelayChatDelta`) with `UNAUTHENTICATED` — while HTTP queries, which
 * carry a real `Authorization` header, worked. The plan chat therefore never updated live.
 */

/**
 * The `connection_init` payload: every header at the TOP level (what the worker reads), and the
 * same map under `headers` too, for a server that reads that shape.
 */
export function connectionInitPayload(headers: Readonly<Record<string, string>>): Record<string, unknown> {
  return { ...headers, headers: { ...headers } };
}

/** Retry a subscription once after an auth failure, and only when the app can refresh its token. */
export function shouldRetrySubscriptionAuth(
  alreadyRetried: boolean,
  canRefresh: boolean,
  isAuthFailure: boolean,
): boolean {
  return !alreadyRetried && canRefresh && isAuthFailure;
}
